//! Music: four stems that loop together, generated by `tools/sfx` and
//! embedded in the binary.
//!
//! The grey base always plays in a level; the red,
//! green and blue stems fade in as those colours are restored, so the music
//! fills out as the level does. The title and the campaign's end play every
//! stem, as do the settings, so the music can be heard while setting its
//! volume; game over plays only the base. Presentation only.

use std::sync::Arc;

use bevy::audio::{AudioSinkPlayback, Volume};
use bevy::prelude::*;

use crate::light::{Primary, Spectrum};
use crate::screens::Screen;
use crate::sound::{SoundSettings, approach};

/// One of the music's stems. Names match the files `tools/sfx` writes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Stem {
    Base,
    Red,
    Green,
    Blue,
}

impl Stem {
    pub const ALL: [Self; 4] = [Self::Base, Self::Red, Self::Green, Self::Blue];

    /// The generated file's name, without extension.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Base => "music_base",
            Self::Red => "music_red",
            Self::Green => "music_green",
            Self::Blue => "music_blue",
        }
    }

    /// The embedded WAV data.
    #[must_use]
    pub const fn bytes(self) -> &'static [u8] {
        match self {
            Self::Base => include_bytes!("../assets/audio/music_base.wav"),
            Self::Red => include_bytes!("../assets/audio/music_red.wav"),
            Self::Green => include_bytes!("../assets/audio/music_green.wav"),
            Self::Blue => include_bytes!("../assets/audio/music_blue.wav"),
        }
    }

    /// The colour that brings this stem in; the base has none.
    #[must_use]
    pub const fn primary(self) -> Option<Primary> {
        match self {
            Self::Base => None,
            Self::Red => Some(Primary::Red),
            Self::Green => Some(Primary::Green),
            Self::Blue => Some(Primary::Blue),
        }
    }
}

/// A playing stem.
#[derive(Component, Debug, Clone, Copy, PartialEq, Eq)]
pub struct MusicStem(pub Stem);

/// How fast stems fade in and out (per second): a colour's layer swells in
/// over a couple of seconds.
const MUSIC_FADE_RATE: f32 = 1.5;

/// The music's level while the game is paused.
pub const PAUSED_LEVEL: f32 = 0.4;

/// How loud `stem` should be, from 0 to 1, on `screen` (none means
/// playing) with the primaries `restored`.
#[must_use]
pub const fn stem_level(stem: Stem, screen: Option<Screen>, restored: [bool; 3]) -> f32 {
    let on = match (screen, stem.primary()) {
        (_, None) | (Some(Screen::Title | Screen::Settings | Screen::Finished), _) => true,
        (Some(Screen::GameOver), Some(_)) => false,
        (Some(Screen::Playing) | None, Some(primary)) => restored[primary.index()],
    };
    if on { 1.0 } else { 0.0 }
}

#[derive(Debug, Default)]
pub struct MusicPlugin;

impl Plugin for MusicPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(Startup, spawn_music)
            .add_systems(Update, drive_music);
    }
}

/// Start every stem together, silent, so they stay in time; `drive_music`
/// sets how loud each is.
fn spawn_music(mut commands: Commands, mut sources: ResMut<Assets<AudioSource>>) {
    for stem in Stem::ALL {
        let source = sources.add(AudioSource {
            bytes: Arc::from(stem.bytes()),
        });
        commands.spawn((
            Name::new(format!("Music {}", stem.name())),
            MusicStem(stem),
            AudioPlayer(source),
            PlaybackSettings::LOOP.with_volume(Volume::SILENT),
        ));
    }
}

/// Fade each stem towards its level, scaled by the music and master
/// volumes and lowered while paused. Real time, as menus stop the game
/// clock but not the music.
fn drive_music(
    time: Res<Time<Real>>,
    virtual_time: Res<Time<Virtual>>,
    settings: Res<SoundSettings>,
    screen: Option<Res<State<Screen>>>,
    spectrum: Option<Res<Spectrum>>,
    mut stems: Query<(&MusicStem, &mut AudioSink)>,
) {
    let screen = screen.map(|s| *s.get());
    let restored = spectrum.map_or([false; 3], |s| s.restored);
    let paused = virtual_time.is_paused() && matches!(screen, None | Some(Screen::Playing));
    let volume = settings.music * settings.master * if paused { PAUSED_LEVEL } else { 1.0 };
    for (stem, mut sink) in &mut stems {
        let target = stem_level(stem.0, screen, restored) * volume;
        let next = approach(
            sink.volume().to_linear(),
            target,
            MUSIC_FADE_RATE,
            time.delta_secs(),
        );
        sink.set_volume(Volume::Linear(next));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn colours_bring_in_their_stems_in_play() {
        let none = [false; 3];
        let red_only = [true, false, false];
        for screen in [None, Some(Screen::Playing)] {
            assert!((stem_level(Stem::Base, screen, none) - 1.0).abs() < f32::EPSILON);
            assert!(stem_level(Stem::Red, screen, none).abs() < f32::EPSILON);
            assert!((stem_level(Stem::Red, screen, red_only) - 1.0).abs() < f32::EPSILON);
            assert!(stem_level(Stem::Blue, screen, red_only).abs() < f32::EPSILON);
        }
    }

    #[test]
    fn the_title_plays_everything_and_game_over_only_the_base() {
        for stem in Stem::ALL {
            for screen in [Screen::Title, Screen::Settings, Screen::Finished] {
                assert!((stem_level(stem, Some(screen), [false; 3]) - 1.0).abs() < f32::EPSILON);
            }
            let over = stem_level(stem, Some(Screen::GameOver), [true; 3]);
            assert_eq!(over > 0.0, stem == Stem::Base, "{stem:?}");
        }
    }

    #[test]
    fn every_stem_is_a_wav_of_the_same_length() {
        let sizes: Vec<usize> = Stem::ALL.iter().map(|s| s.bytes().len()).collect();
        assert!(sizes.iter().all(|&size| size == sizes[0]));
        for stem in Stem::ALL {
            assert_eq!(&stem.bytes()[..4], b"RIFF", "{}", stem.name());
        }
    }

    #[test]
    fn every_stem_starts_together() {
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .init_resource::<Assets<AudioSource>>()
            .init_resource::<SoundSettings>()
            .add_plugins(MusicPlugin);
        app.update();
        let world = app.world_mut();
        let mut stems: Vec<Stem> = world
            .query::<&MusicStem>()
            .iter(world)
            .map(|s| s.0)
            .collect();
        stems.sort_by_key(|s| s.name());
        let mut all = Stem::ALL.to_vec();
        all.sort_by_key(|s| s.name());
        assert_eq!(stems, all);
    }
}
